SELECT action,reason,created_at FROM solution_moderation_action
WHERE target_type='COMMENT' AND target_id=#{commentId} AND author_id=#{authorId}
ORDER BY action_id DESC LIMIT 50

SELECT action_id,solution_id,target_type,target_id,author_id,operator_id,action,reason,created_at FROM solution_moderation_action WHERE target_type='COMMENT' AND target_id IN
#{targetId}
ORDER BY action_id DESC

SELECT action_id, solution_id, target_type, target_id, author_id, operator_id, action, reason, created_at
FROM solution_moderation_action WHERE solution_id = #{solutionId}
ORDER BY action_id DESC LIMIT #{offset}, #{limit}
